const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np
from scipy.sparse import csr_array, csc_array
from pyamg.classical import (aggressive_strength_of_connection,
    interpolation_passes, multipass_interpolation, truncate_interpolation,
    jacobi_improve_interpolation, sparsify_coarse_operator)
rng = np.random.default_rng(4)
for n in range(2, 9):
  for degree in range(2, 5):
    for _ in range(30):
      dense=(rng.random((n,n))<.25).astype(float); np.fill_diagonal(dense,0)
      split=rng.integers(0,2,n); split[0]=1
      got=aggressive_strength_of_connection(csr_array(dense),split,degree).toarray()
      expected=np.zeros((n,n),int); coarse=split!=0
      for source in np.flatnonzero(coarse):
       found={}
       def walk(path):
        point=path[-1]
        if len(path)>1 and coarse[point]:
         if point!=source: found.setdefault(point,set()).update(path[1:-1])
         return
        if len(path)-1==degree:return
        for nxt in np.flatnonzero(dense[point]):
         if nxt not in path:walk(path+[int(nxt)])
       walk([int(source)])
       for target,points in found.items():expected[source,target]=len(points)
      assert np.array_equal(got,expected)
A=csr_array([[4.,-1,0,0],[-1,4,-1,0],[0,-1,4,-1],[0,0,-1,2]])
s=np.array([1,0,0,0]); assert np.array_equal(interpolation_passes(A,A,s),[0,1,2,3])
P=multipass_interpolation(A,A,s); assert P.has_sorted_indices and not np.any(P.data==0)
Pc=multipass_interpolation(A.astype(complex)*(1+1j),A,s); assert np.iscomplexobj(Pc.data)
T0=csr_array([[.1,.9],[1,-1],[0,0]]); T=truncate_interpolation(T0,.5)
assert np.allclose(T.toarray(),[[0,1],[1,-1],[0,0]])
split=np.array([1,0,1,0]); P0=csr_array([[1,0],[.5,.5],[0,1],[.2,.8]])
J=jacobi_improve_interpolation(A,P0,split,degree=2); assert np.allclose(J[[0,2]].toarray(),np.eye(2))
M=csr_array([[3.,.01,-1],[.02,4,-.5],[-1,-.5,2]])
for symmetric in (False,True):
 for lump in ('none','diagonal','strong'):
  B=np.array([1.,2.,3.]); Q=sparsify_coarse_operator(M,.6,lump,symmetric,B)
  if lump!='none':assert np.allclose(Q@B,M@B)
  assert Q.has_sorted_indices
for fn,args in [(aggressive_strength_of_connection,(csc_array(A),s)),(multipass_interpolation,(csc_array(A),A,s)),(truncate_interpolation,(csc_array(P0),.2)),(jacobi_improve_interpolation,(csc_array(A),P0,split)),(sparsify_coarse_operator,(csc_array(A),))]:
 try:fn(*args)
 except TypeError:pass
 else:raise AssertionError(fn)
print('custom checks passed')
