const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np
from pyamg.gallery import poisson
from pyamg.classical import ruge_stuben_solver
A=poisson((100,),format='csr')
a=ruge_stuben_solver(A,CF='aggressive',aggressive_levels=0,max_coarse=3)
r=ruge_stuben_solver(A,CF='RS',max_coarse=3)
